begin;
create temp table tmp_gab_diaries (src_row int, date date, operator_name text, equipment_type text, equipment_fleet text, ogs_number text, client_name text, location_address text, work_status text, period text, odometer_initial numeric, odometer_final numeric, observations text);
create temp table tmp_gab_times (src_row int, start_time time, end_time time, activity text, description text);
create temp table tmp_inserted_diaries as with ins as (
select 'a1b2c3d4-e5f6-7890-abcd-ef1234567890'::uuid,t.date,t.operator_name,t.equipment_type,t.equipment_fleet,t.ogs_number,t.client_name,t.location_address,t.odometer_initial,t.odometer_final,t.work_status,t.period,t.observations,'enviado','01e48480-d95b-47b8-a7b1-e77af33d39e7'::uuid,'01e48480-d95b-47b8-a7b1-e77af33d39e7'::uuid,e.id
from tmp_gab_diaries t left join equipamentos e on e.company_id='a1b2c3d4-e5f6-7890-abcd-ef1234567890'::uuid and e.frota=t.equipment_fleet
where not exists (select 1 from equipment_diaries ed where ed.company_id='a1b2c3d4-e5f6-7890-abcd-ef1234567890'::uuid and ed.status='enviado' and coalesce(ed.user_id,ed.created_by)='01e48480-d95b-47b8-a7b1-e77af33d39e7'::uuid and ed.date=t.date and coalesce(ed.operator_name,'')=coalesce(t.operator_name,'') and coalesce(ed.equipment_type,'')=coalesce(t.equipment_type,'') and coalesce(ed.equipment_fleet,'')=coalesce(t.equipment_fleet,'') and coalesce(ed.ogs_number,'')=coalesce(t.ogs_number,'') and coalesce(ed.client_name,'')=coalesce(t.client_name,'') and coalesce(ed.location_address,'')=coalesce(t.location_address,'') and coalesce(ed.work_status,'')=coalesce(t.work_status,'') and coalesce(ed.period,'')=coalesce(t.period,'') and ed.odometer_initial is not distinct from t.odometer_initial and ed.odometer_final is not distinct from t.odometer_final)
returning id, date, equipment_fleet ) select * from ins;
create temp table tmp_resolved as select t.src_row,(select ed.id from equipment_diaries ed where ed.company_id='a1b2c3d4-e5f6-7890-abcd-ef1234567890'::uuid and ed.status='enviado' and coalesce(ed.user_id,ed.created_by)='01e48480-d95b-47b8-a7b1-e77af33d39e7'::uuid and ed.date=t.date and coalesce(ed.operator_name,'')=coalesce(t.operator_name,'') and coalesce(ed.equipment_type,'')=coalesce(t.equipment_type,'') and coalesce(ed.equipment_fleet,'')=coalesce(t.equipment_fleet,'') and coalesce(ed.ogs_number,'')=coalesce(t.ogs_number,'') and coalesce(ed.client_name,'')=coalesce(t.client_name,'') and coalesce(ed.location_address,'')=coalesce(t.location_address,'') and coalesce(ed.work_status,'')=coalesce(t.work_status,'') and coalesce(ed.period,'')=coalesce(t.period,'') and ed.odometer_initial is not distinct from t.odometer_initial and ed.odometer_final is not distinct from t.odometer_final order by ed.created_at desc limit 1) as diary_id from tmp_gab_diaries t;
create temp table tmp_inserted_times as with ins as (
select r.diary_id,tt.start_time,tt.end_time,tt.activity,nullif(tt.description,''),'a1b2c3d4-e5f6-7890-abcd-ef1234567890'::uuid from tmp_gab_times tt join tmp_resolved r on r.src_row=tt.src_row where r.diary_id is not null and not exists (select 1 from equipment_time_entries te where te.diary_id=r.diary_id and te.start_time is not distinct from tt.start_time and te.end_time is not distinct from tt.end_time and coalesce(te.activity,'')=coalesce(tt.activity,'') and coalesce(te.description,'')=coalesce(nullif(tt.description,''),'')) returning id,diary_id ) select * from ins;
select 'tmp_gab_diaries' as etapa,count(*)::int as qtd from tmp_gab_diaries union all select 'tmp_gab_times',count(*)::int from tmp_gab_times union all select 'inserted_diaries',count(*)::int from tmp_inserted_diaries union all select 'inserted_times',count(*)::int from tmp_inserted_times;
select equipment_fleet,count(*)::int as novos_diarios from tmp_inserted_diaries group by equipment_fleet order by equipment_fleet;
commit;
